// Track B / B4: `storage`/`react-native` used to be static top-level
// imports. That's fine inside the app bundle, but it means nothing could
// ever import this file's `translations` data from plain Node tooling
// (an i18n symmetry/raw-key checker, for example) without react-native's
// native-module bridging throwing outside Metro — and it meant a failure
// inside `storage.js` on ANY platform would produce an unhandled promise
// rejection from the IIFE below (no .catch() existed). Lazily required,
// same pattern as `getLocalization()` right below, which already did this
// correctly for expo-localization.
let _storage;
function getStorage() {
  if (_storage !== undefined) return _storage;
  try { _storage = require('./storage').storage; } catch { _storage = null; }
  return _storage;
}
let _RN;
function getRN() {
  if (_RN !== undefined) return _RN;
  try { _RN = require('react-native'); } catch { _RN = null; }
  return _RN;
}
// PR-C2 (Task C auto-detect): expo-localization выдаёт надёжный locale
// на iOS/Android — лучше чем NativeModules.SettingsManager.AppleLocale
// (deprecated в новых RN). Лоадим лениво чтобы web-bundle не тащил
// нативный модуль.
let _Localization;
function getLocalization() {
  if (_Localization !== undefined) return _Localization;
  try { _Localization = require('expo-localization'); } catch { _Localization = null; }
  return _Localization;
}

const listeners = new Set();
const KEY = 'ur_lang';

// Алиасы: системный код → наш код.
//
// Stage 7 standardised the codes to ISO. Earlier the storage might
// have written `'KZ'` (country code, not language) or `'CN'` (also
// country code) into `ur_lang`; the loader below now redirects those
// legacy values to the proper language code so users don't lose
// their choice on upgrade.
//
// I18N-16 (2026-09-12): expanded from 4 to 16 locales. IMPORTANT —
// language ≠ country (item 9 of the i18n expansion spec): every alias
// below maps a BCP-47 *language* subtag (optionally with a region
// subtag for disambiguation, e.g. `zh-tw`) to our internal code. None
// of this infers a language from a device region/country alone — a
// `de-CH` or `fr-CA` system locale still resolves via the bare `de`/
// `fr` base-code fallback in detectSystemLang()/currentLang above,
// never from the country half. Traditional-Chinese system locales
// (`zh-hant`, `zh-tw`, `zh-hk`) still route into the Simplified `ZH`
// dictionary — this app ships Simplified Chinese only, by design (see
// CLAUDE.md); we are not adding a separate Traditional dictionary.
const LANG_ALIAS = {
  ru: 'RU', rus: 'RU',
  en: 'EN', eng: 'EN',
  kk: 'KK', kaz: 'KK', 'kk-kz': 'KK',
  zh: 'ZH', 'zh-cn': 'ZH', 'zh-hans': 'ZH', 'zh-hant': 'ZH', 'zh-tw': 'ZH', 'zh-hk': 'ZH',
  uz: 'UZ', 'uz-uz': 'UZ', 'uz-latn': 'UZ',
  ky: 'KY', kir: 'KY', kg: 'KY',
  tg: 'TG', tgk: 'TG',
  de: 'DE', deu: 'DE', ger: 'DE',
  fr: 'FR', fra: 'FR', fre: 'FR',
  pl: 'PL', pol: 'PL',
  lt: 'LT', lit: 'LT',
  lv: 'LV', lav: 'LV',
  it: 'IT', ita: 'IT',
  tr: 'TR', tur: 'TR',
  be: 'BE', bel: 'BE',
  ro: 'RO', ron: 'RO', rum: 'RO',
};

// Legacy persisted-value fixups. Stage 5 narrowed the set to four
// languages and renamed two of them in Stage 7 (KZ→KK, CN→ZH).
// Anything else falls through to system detect / RU.
const LEGACY_LANG_FIX = {
  KZ: 'KK',
  CN: 'ZH',
};

// Sync detect at module load — best effort before async storage
// PR-C2: default fallback на 'EN' вместо 'RU' — для пользователей с
// неподдерживаемым языком устройства это даёт более универсальный first-run
// experience. RU/KK/ZH юзеры всё равно попадают в свою локаль через alias.
let currentLang = (() => {
  try {
    let code = '';
    if (typeof navigator !== 'undefined' && navigator.language) {
      code = navigator.language.toLowerCase();
    }
    if (!code) return 'EN';
    const base = code.split('-')[0];
    if (LANG_ALIAS[code]) return LANG_ALIAS[code];
    if (LANG_ALIAS[base]) return LANG_ALIAS[base];
    return 'EN'; // unsupported → EN
  } catch { return 'EN'; }
})();

function detectSystemLang() {
  let code;
  try {
    // PR-C2: предпочитаем expo-localization (Localization.getLocales() в
    // SDK 52, или Localization.locale в legacy). Это работает на новых
    // iOS / Android без NativeModules deprecation warnings.
    const RN = getRN();
    const platformOS = RN?.Platform?.OS;
    if (platformOS !== 'web') {
      const Loc = getLocalization();
      if (Loc) {
        try {
          // SDK 52 API: getLocales() возвращает array of { languageTag, … }
          const locales = Loc.getLocales?.();
          if (Array.isArray(locales) && locales.length && locales[0].languageTag) {
            code = String(locales[0].languageTag).toLowerCase();
          }
        } catch {}
        if (!code && Loc.locale) {
          code = String(Loc.locale).toLowerCase().replace('_', '-');
        }
      }
    }
    if (!code) {
      if (platformOS === 'web' && typeof navigator !== 'undefined') {
        code = (navigator.language || navigator.userLanguage || '').toLowerCase();
      } else {
        const locale =
          RN?.NativeModules?.SettingsManager?.settings?.AppleLocale ||
          RN?.NativeModules?.SettingsManager?.settings?.AppleLanguages?.[0] ||
          RN?.NativeModules?.I18nManager?.localeIdentifier ||
          '';
        code = locale.toLowerCase().replace('_', '-');
      }
    }
  } catch {
    code = '';
  }
  if (!code) return null;
  // пробуем полный код, потом основу
  if (LANG_ALIAS[code]) return LANG_ALIAS[code];
  const base = code.split('-')[0];
  if (LANG_ALIAS[base]) return LANG_ALIAS[base];
  return null;
}

// Load saved language on start; если не выбран — авто из системы.
// PR-C2: если detect ничего не нашёл — устанавливаем EN (универсальный
// fallback для приграничных пользователей с экзотическими locale).
//
// Track B / B4: this used to have no try/catch and no .catch() on the IIFE
// itself — any failure inside storage.get/set (any platform, any reason)
// produced an unhandled promise rejection with no fallback. Now: any
// failure just keeps the sync-detected `currentLang` from module load
// (never worse than before this ran), and is caught rather than left
// unhandled — which also happens to be what makes this file safely
// importable from plain Node tooling (a symmetry/raw-key checker) where
// storage is unavailable at all.
(async () => {
  try {
    const store = getStorage();
    let saved = await store?.get(KEY);
    // Legacy fix-up: rewrite `KZ` → `KK`, `CN` → `ZH` for users
    // upgrading from a Stage 5 build.
    if (saved && LEGACY_LANG_FIX[saved]) {
      saved = LEGACY_LANG_FIX[saved];
      store?.set(KEY, saved);
    }
    if (saved && translations[saved]) {
      currentLang = saved;
    } else {
      const sys = detectSystemLang();
      if (sys && translations[sys]) {
        currentLang = sys;
        store?.set(KEY, sys); // сохраняем выбор авто
      } else if (!translations[currentLang]) {
        currentLang = 'EN';
        store?.set(KEY, 'EN');
      }
    }
    syncDocumentLanguage(currentLang);
    listeners.forEach(cb => cb(currentLang));
  } catch {
    // Best-effort: keep whatever currentLang the synchronous detect at
    // module load already picked.
  }
})();

const HTML_LANG = {
  RU: 'ru', KK: 'kk', ZH: 'zh-CN', EN: 'en',
  UZ: 'uz', KY: 'ky', TG: 'tg', DE: 'de', FR: 'fr', PL: 'pl',
  LT: 'lt', LV: 'lv', IT: 'it', TR: 'tr', BE: 'be', RO: 'ro',
};

const syncDocumentLanguage = (lang) => {
  // The browser translator was appearing above the Chinese UI because the
  // document stayed marked as English. Native builds have no `document`.
  if (typeof document !== 'undefined' && document.documentElement) {
    document.documentElement.lang = HTML_LANG[lang] || 'en';
  }
};

export const setLanguage = (lang) => {
  currentLang = translations[lang] ? lang : 'EN';
  getStorage()?.set(KEY, currentLang);
  syncDocumentLanguage(currentLang);
  listeners.forEach(cb => cb(currentLang));
  // Push/Outbox/Localization repair (2026-09-11): push_devices.locale is
  // otherwise only ever captured once, at push.autoRegister() (OTP/login) —
  // a user who changes the in-app language afterwards kept receiving
  // system push text in whatever language was active at login for the
  // rest of that session (confirmed root cause of a device showing the
  // right UI language while its push notifications arrived in a stale
  // one). Fire-and-forget, lazy require (push.js is native-module-heavy
  // and i18n.js is imported far too widely to eagerly pull it in) — never
  // touches native permission APIs, see push.refreshLocale()'s own
  // docstring for why that matters here specifically.
  try {
    require('./push').push.refreshLocale?.().catch(() => {});
  } catch {
    // best-effort only — must never block a language switch
  }
};

export const getLanguage = () => currentLang;

export const subscribeToLanguage = (cb) => {
  listeners.add(cb);
  return () => listeners.delete(cb);
};

export const t = (key) => {
  // Track B / B4 (2026-09-08): a prior audit flagged this as "should also
  // fall back to RU for KK/ZH, not just EN" and it was briefly changed that
  // way here — reverted. qa/utils/zhLocalizationSmoke.js encodes this as a
  // deliberate, tested product rule: "Chinese UI uses Chinese system copy
  // ...; it must never fall back to Russian" — the same policy applies to
  // KK. EN is the intentional universal fallback, not an oversight. Do not
  // add a translations.RU[key] step here without updating/removing that
  // rule (and the same one in useI18n.js) first, with product sign-off.
  const lang = translations[currentLang];
  if (lang && lang[key]) return lang[key];
  if (currentLang !== 'RU') return translations.EN[key] || key;
  return translations.RU[key] || translations.EN[key] || key;
};

// Склонение для русского: 1 ставка, 2 ставки, 5 ставок
function pluralRu(n, one, few, many) {
  const abs = Math.abs(n) % 100;
  const last = abs % 10;
  if (abs >= 11 && abs <= 14) return many;
  if (last === 1) return one;
  if (last >= 2 && last <= 4) return few;
  return many;
}

export const formatBids = (count) => {
  const n = count || 0;
  // Единая терминология: «предложение» (как в колоколе «Новое предложение» и
  // вкладке «Предложения»), а не «ставка» — одно слово во всём флоу сделки.
  if (currentLang === 'RU') {
    return `${n} ${pluralRu(n, 'предложение', 'предложения', 'предложений')}`;
  }
  return `${n} ${t('bids')}`;
};

export const formatStatus = (status) => {
  const key = `status_${status}`;
  const val = t(key);
  return val !== key ? val : t('status_unknown');
};

const LEGACY_TRUCK_TYPE_KEYS = {
  'Тент': 'tent',
  'Фура': 'tent',
  'Рефрижератор': 'ref',
  'Изотерм': 'izoterm',
  'Бортовой': 'open_truck',
  'Площадка': 'platform',
  'Автовоз': 'auto',
  'Цистерна': 'tanker',
  "Контейнер 20'": 'cont20',
  "Контейнер 40'": 'cont40',
  'Контейнер 20′': 'cont20',
  'Контейнер 40′': 'cont40',
};

export const formatTruckType = (type) => {
  if (!type) return t('cargo_type_unknown');
  const raw = String(type).trim();
  const val = t(raw);
  if (val !== raw) return val;
  const legacyKey = LEGACY_TRUCK_TYPE_KEYS[raw];
  if (legacyKey) return t(legacyKey);
  return currentLang === 'RU' ? raw : (translations.EN[raw] || t('cargo_type_unknown'));
};

export const formatCargoType = (type) => {
  if (!type) return t('cargo_type_unknown');
  const raw = String(type).trim();
  const val = t(raw);
  if (val !== raw) return val;
  return localizeCargoName(raw, currentLang) || raw;
};

export default translations;
